# *#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#
# Preprocessing Pipeline part 1  #
# *#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#
#
# This script executes the complete preprocessing
# workflow for a single participant.
#
# Processing steps:
#   00) Bad channel detection + Maxwell filtering
#   01) PREP pipeline
#   02) Artifact annotation
#   03) ICA training
#
# Outputs generated by each step are saved and used
# by the next step independently.

# avlDJSVGDçasd
# *#*#*#*#*#
# 1) Setup #
# *#*#*#*#*#
import mne
from pathlib import Path
from paths import create_output_folders
from step00_badch_maxwell import run_badch_maxwell
from step01_prep_pipeline import run_prep_pipeline
from step02_artifact_annotations import run_artifact_annotations
from step03_ica import run_train_ica
from THE_DELETER import the_deleter


# *#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#
# 2) Full preprocessing part 1  #
# *#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#


def run_full_pipeline_part1(subject):

    # *#*#*#*#*#*#*#
    # 2.1) Paths  #
    # *#*#*#*#*#*#*#
    # Define input/output directories and create
    # the preprocessing folder structure.
    # Locate all raw duration runs and create
    # standardized run names.

    # subjects that didn't pass the qc --> professor tava a pensar em fazer para ele ir
    # buscar a tabela mas sao so 3 e eu estou me a sentir preguiçoso

    EXCLUDED_SUBJECTS = {"CA101", "CA108", "CB082"}

    if subject in EXCLUDED_SUBJECTS:
        print(f"{subject}: excluído pelo QC oficial. A saltar sujeito.")
        return

    # inroot_dir = Path(r"C:\Users\tomas\Desktop\COG_MEEG_EXP1_RELEASE")
    inroot_dir = Path("/home/blab/COGITATE/DATA/COG_MEEG_EXP1_RELEASE")
    

    # sub_indir = Path(rf"C:\Users\tomas\Desktop\COG_MEEG_EXP1_RELEASE\{subject}")
    sub_indir = inroot_dir / subject
    sub_dur_indir = sub_indir / f"{subject}_EXP1_MEEG"

    out_paths = create_output_folders(subject=subject, inroot=inroot_dir)

    raw_files = sorted(sub_dur_indir.glob("*DurR*.fif"))

    names = [f"dur{i + 1}" for i in range(len(raw_files))]

    raw_info = mne.io.read_raw_fif(raw_files[0], preload=False)
    has_eeg = len(mne.pick_types(raw_info.info, eeg=True)) > 0
    raw_info.close()

    print(f"{subject}: has_eeg = {has_eeg}")

    # *#*#*#*#*#*#*#*#*#*#*#*#*#
    # 2.2) Maxwell filtering  #
    # *#*#*#*#*#*#*#*#*#*#*#*#*#
    # Detects bad channels, applies Signal Space
    # Separation (SSS), interpolate bad channels
    # and aligns runs to a common head position.

    use_maxwell = True

    raws_sss = None

    if use_maxwell:
        raws_sss = run_badch_maxwell(
            file_paths=raw_files,
            cal_file=sub_indir
            / "metadata/calibration_crosstalk_coreg"
            / f"{subject}_ses-1_acq-calibration_meg.dat",
            ct_file=sub_indir
            / "metadata/calibration_crosstalk_coreg"
            / f"{subject}_ses-1_acq-crosstalk_meg.fif",
            out_paths=out_paths,
            subject=subject,
            names=names,
            save_outputs=True,
        )
    if raws_sss is None:
        sss_files = sorted(
            out_paths["00_badch_maxwell"].glob(f"{subject}_00_badch_maxwell_*_raw.fif")
        )

        if len(sss_files) > 0:
            print(f"{subject}: a carregar ficheiros SSS existentes.")
            raws_sss = [mne.io.read_raw_fif(f, preload=False) for f in sss_files]

    if raws_sss is None:
        print(f"{subject}: não existem ficheiros SSS - a usar raws originais.")
        raws_sss = [mne.io.read_raw_fif(f, preload=False) for f in raw_files]

    # *#*#*#*#*#*#
    # 2.3) PREP  #
    # *#*#*#*#*#*#
    # Applies robust EEG preprocessing including
    # line-noise removal, referencing and bad
    # channel interpolation.

    if has_eeg:
        raws_clean = run_prep_pipeline(
            raws_sss=raws_sss,
            out_paths=out_paths,
            subject=subject,
            names=names,
            save_outputs=True,
        )

        the_deleter(out_paths=out_paths, folder="00_badch_maxwell")

    else:
        print(f"{subject}: sem EEG - a saltar PREP pipeline.")
        raws_clean = raws_sss

    # the_deleter(out_paths=out_paths, folder="00_badch_maxwell")

    # raws_clean = None
    if not raws_clean:
        # if raws_clean is None:
        file_paths = sorted(
            out_paths["01_prep_pipeline"].glob(f"{subject}_01_prep_pipeline_*_raw.fif")
        )
        raws_clean = [mne.io.read_raw_fif(f, preload=False) for f in file_paths]

    # ola tomas do futuro se isto der erro é provavel que seja por causa do preload false, antes tava true acho que ha um codigo que da load a data mas nao me lembro gl
    # for raw_clean in raws_clean
    #   raw_clean.load_data() pronto o deepy foi simpatico

    # prep_files = [
    #    out_paths["01_prep_pipeline"] / f"{subject}_01_prep_pipeline_{n}_raw.fif"
    #    for n in names
    # ]

    # *#*#*#*#*#*#*#*#*#*#*#*##*#
    # 2.4) Artifact annotation #
    # *#*#*#*#*#*#*#*#*#*#*#*##*#
    # Automatically identifies segments containing
    # large artifacts and stores them as annotations
    # for later exclusion.

    raws_annotated = run_artifact_annotations(
        raws_clean=raws_clean,
        out_paths=out_paths,
        subject=subject,
        names=names,
        save_outputs=True,
    )

    the_deleter(out_paths=out_paths, folder="01_prep_pipeline")

    if not raws_annotated:
        file_paths = sorted(
            out_paths["02_artifact_annotations"].glob(
                f"{subject}_02_artifact_annotations_*_raw.fif"
            )
        )
        raws_annotated = [mne.io.read_raw_fif(f, preload=False) for f in file_paths]

    # annot_files = [
    #    out_paths["02_artifact_annotations"]
    #    / f"{subject}_02_artifact_annotations_{n}_raw.fif"
    #    for n in names
    # ]

    # *#*#*#*#*#*#*#*#*#
    # 2.6) ICA train  #
    # *#*#*#*#*#*#*#*#*#
    # Trains independent component decompositions
    # for MEG and EEG and identifies candidates for
    # physiological artifact components.

    run_train_ica(
        raws_annotated=raws_annotated,
        out_paths=out_paths,
        subject=subject,
        names=names,
        save_outputs=True,
        has_eeg=has_eeg,
    )

    print(f"{subject} preprocessing part 1 completed.")


if __name__ == "__main__":
    run_full_pipeline_part1("CA101")

